def zigzag_check(lst):
    n = len(lst)
    if n < 2:
        return True
    for i in range(n - 1):
        if lst[i] == lst[i + 1]:
            return False
    if n == 2:
        return True
    for i in range(1, n - 1):
        left = lst[i - 1]
        right = lst[i + 1]
        cur = lst[i]
        if not ((cur > left and cur > right) or (cur < left and cur < right)):
            return False
    return True

def sign_changes_count(lst):
    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
    count = 0
    for i in range(len(lst) - 1):
        if sign(lst[i]) != sign(lst[i + 1]):
            count += 1
    return count

def count_strictly_increasing_pairs(lst):
    count = 0
    for i in range(len(lst) - 1):
        if lst[i + 1] > lst[i]:
            count += 1
    return count

def count_strictly_decreasing_pairs(lst):
    count = 0
    for i in range(len(lst) - 1):
        if lst[i + 1] < lst[i]:
            count += 1
    return count

def is_geometric_sequence(lst):
    n = len(lst)
    if n <= 1:
        return True
    a0, a1 = lst[0], lst[1]
    for i in range(n - 1):
        if lst[i + 1] * a0 != a1 * lst[i]:
            return False
    return True

def max_gap_between_elements(lst):
    if len(lst) < 2:
        return 0
    s = sorted(lst)
    return max(s[i + 1] - s[i] for i in range(len(s) - 1))

def count_local_maxima_including_endpoints(lst):
    n = len(lst)
    if n == 0:
        return 0
    if n == 1:
        return 1
    count = 0
    for i in range(n):
        if i == 0:
            if lst[i] > lst[i + 1]:
                count += 1
        elif i == n - 1:
            if lst[i] > lst[i - 1]:
                count += 1
        else:
            if lst[i] > lst[i - 1] and lst[i] > lst[i + 1]:
                count += 1
    return count

def first_index_running_sum_exceeds(lst, target):
    total = 0
    for i, x in enumerate(lst):
        total += x
        if total > target:
            return i
    return -1

def running_sum_reset_on_negative(lst):
    result = []
    total = 0
    for x in lst:
        total += x
        if total < 0:
            total = 0
        result.append(total)
    return result

def longest_positive_run_sum(lst):
    best_len = 0
    best_sum = 0
    cur_len = 0
    cur_sum = 0
    for x in lst:
        if x > 0:
            cur_len += 1
            cur_sum += x
        else:
            if cur_len > best_len:
                best_len = cur_len
                best_sum = cur_sum
            cur_len = 0
            cur_sum = 0
    if cur_len > best_len:
        best_len = cur_len
        best_sum = cur_sum
    return best_sum

def interleave_two_sorted_lists(a, b):
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def shift_left_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return lst[n:] + [fill] * n

def first_missing_positive(lst):
    s = set(lst)
    i = 1
    while i in s:
        i += 1
    return i

def compress_ranges(lst):
    if not lst:
        return []
    result = []
    start = lst[0]
    prev = lst[0]
    for x in lst[1:]:
        if x == prev + 1:
            prev = x
        else:
            result.append([start, prev])
            start = x
            prev = x
    result.append([start, prev])
    return result

def max_product_of_two(lst):
    s = sorted(lst)
    return max(s[-1] * s[-2], s[0] * s[1])

def min_absolute_difference_pair(lst):
    s = sorted(lst)
    return min(s[i + 1] - s[i] for i in range(len(s) - 1))

def longest_common_prefix_length(list_of_lists):
    if not list_of_lists:
        return 0
    min_len = min(len(l) for l in list_of_lists)
    count = 0
    for i in range(min_len):
        val = list_of_lists[0][i]
        if all(l[i] == val for l in list_of_lists):
            count += 1
        else:
            break
    return count
